 "content": "def transform(grid):
    """Reconstruct 2-masked cells using the grid's dihedral symmetry."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2:
                continue
            if h == w:
                n = h
                orbit = {
                    (r, c), (c, r), (r, n - 1 - c), (n - 1 - c, r),
                    (n - 1 - r, c), (c, n - 1 - r),
                    (n - 1 - r, n - 1 - c),
                    (n - 1 - c, n - 1 - r),
                }
            else:
                orbit = {(r, c), (r, w - 1 - c),
                         (h - 1 - r, c), (h - 1 - r, w - 1 - c)}
            values = [grid[rr][cc] for rr, cc in orbit
                      if grid[rr][cc] != 2]
            if not values:
                raise ValueError(f"No unmasked symmetric reference for {(r, c)}")
            counts = {value: values.count(value) for value in set(values)}
            out[r][c] = max(counts, key=counts.get)
    return out

